/**
 * Entrada del trabajo de verificación (`podmanJobVerifier.ts`): corre DENTRO
 * del contenedor, sin credencial, y deja su veredicto en `--report`.
 *
 * Salida: 0 verificado; 1 no verificado (la causa va en el reporte);
 * 2 argumentos inválidos, sin reporte.
 */
import { statfsSync } from 'node:fs'
import { mkdir, writeFile } from 'node:fs/promises'
import { dirname } from 'node:path'
import { parseArgs } from 'node:util'

import { verifyPublishedArtifact } from '../artifactVerifier.js'
import { createOciArtifactRegistry } from '../ociArtifactRegistry.js'

const REQUIRED = ['registry', 'repository', 'tag', 'digest', 'work-dir', 'report'] as const

const { values } = parseArgs({ options: Object.fromEntries(REQUIRED.map(name => [name, { type: 'string' }])) as Record<(typeof REQUIRED)[number], { type: 'string' }> })
const missing = REQUIRED.filter(name => !values[name])
if (missing.length > 0) {
  process.stderr.write(`verifyArtifact: faltan ${missing.map(name => `--${name}`).join(', ')}\n`)
  process.exit(2)
}
const option = (name: (typeof REQUIRED)[number]): string => values[name] as string

const workDir = option('work-dir')
await mkdir(workDir, { recursive: true })
const freeBytes = (): number => {
  const stats = statfsSync(workDir)
  return stats.bavail * stats.bsize
}
const consumer = createOciArtifactRegistry({ baseUrl: option('registry'), credential: { kind: 'anonymous' } })
const outcome = await verifyPublishedArtifact(
  { consumer, verifyDir: workDir, freeBytes },
  { repository: option('repository'), digest: option('digest') },
  { repository: option('repository'), tag: option('tag') },
)
await mkdir(dirname(option('report')), { recursive: true })
await writeFile(option('report'), JSON.stringify(outcome, null, 2))
process.stderr.write(`verifyArtifact: ${outcome.status}\n`)
process.exit(outcome.status === 'verified' ? 0 : 1)
#!/usr/bin/env bun
/**
 * Publica un directorio —o un volumen de Podman— como artefacto permanente
 * y lo verifica antes de declarar caché la copia local (TASK-THYROX-0728).
 *
 *   publish-artifact --volume <nombre> | --source-dir <ruta>
 *                    --repository <usuario/repo> --tag <tag>
 *                    --record-file <registro.json> --artifact-type <tipo>
 *                    [--exclude a,b] --out <publicacion.json>
 *
 * La credencial del publicador se lee del `.env` en este proceso y nunca
 * entra al trabajo de verificación, que corre en la primitiva de Podman sin
 * credencial y sin el almacenamiento de esta sesión.
 *
 * Salida: 0 verificado; 1 sin publicar o sin verificar; 2 rehusado antes de
 * empezar (argumentos, credencial, imagen, admisión); 3 límite del provider.
 */
import { spawnSync } from 'node:child_process'
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { parseArgs } from 'node:util'

import { productionDeclarations, thyroxRoot } from '@thyrox/paths/reach.ts'
import { createPodmanExecutor, type PodmanExecutor } from '@thyrox/podman-execution/podmanExecutor.ts'
import { MissingRegistryCredentialError, PUBLISHER_ENV, resolvePublisherCredential } from '@thyrox/registry-credentials/registryCredential.ts'

import { createDiskAdmission } from '../diskAdmission.js'
import { resolveJobEgress, JOB_EGRESS_ENV } from '../jobEgress.js'
import { createOciArtifactRegistry } from '../ociArtifactRegistry.js'
import { createPodmanJobVerifier } from '../podmanJobVerifier.js'
import { publishAndVerify } from '../publishArtifact.js'
import { mediaTypeOf, publicationExitCode, publicationRecord, registryBaseUrl } from '../publishCommand.js'

const REFUSED = 2
const VERIFIER_IMAGE_ENV = 'THYROX_ARTIFACT_VERIFIER_IMAGE'
const DEFAULT_VERIFIER_IMAGE = 'docker.io/library/ubuntu:24.04'
const RUNTIME_HOME_KEY = 'THYROX_RUNTIME_DIR'
const VERIFIER_LIMITS = { cpus: 1, memoryMib: 1024, pidsLimit: 128 }

function refuse(message: string): never {
  process.stderr.write(`publish-artifact: ${message}\n`)
  process.exit(REFUSED)
}

const { values } = parseArgs({
  options: {
    volume: { type: 'string' },
    'source-dir': { type: 'string' },
    repository: { type: 'string' },
    tag: { type: 'string' },
    'record-file': { type: 'string' },
    'artifact-type': { type: 'string' },
    exclude: { type: 'string', default: '' },
    out: { type: 'string' },
  },
})
for (const name of ['repository', 'tag', 'record-file', 'artifact-type', 'out'] as const) {
  if (!values[name]) refuse(`falta --${name}`)
}
if (!values.volume === !values['source-dir']) refuse('declara --volume o --source-dir, uno solo')

const declarations = productionDeclarations()
const declared = (name: string): string | undefined => declarations.declared(name) ?? undefined
const podman: PodmanExecutor = createPodmanExecutor()

async function podmanValue(args: readonly string[], what: string): Promise<string> {
  const result = await podman.run(args)
  const value = result.stdout.trim()
  if (result.exitCode !== 0 || !value) refuse(`no se pudo resolver ${what}: ${result.stderr.trim() || `exit ${result.exitCode}`}`)
  return value
}

const sourceDir = values.volume
  ? await podmanValue(['volume', 'inspect', values.volume, '--format', '{{.Mountpoint}}'], `el volumen ${values.volume}`)
  : (values['source-dir'] as string)

let credential
try {
  credential = resolvePublisherCredential({
    [PUBLISHER_ENV.username]: declared(PUBLISHER_ENV.username),
    [PUBLISHER_ENV.token]: declared(PUBLISHER_ENV.token),
    [PUBLISHER_ENV.registry]: declared(PUBLISHER_ENV.registry),
  })
} catch (error) {
  if (error instanceof MissingRegistryCredentialError) refuse(error.message)
  throw error
}

const egress = (() => {
  try {
    return resolveJobEgress({
      ...process.env,
      [JOB_EGRESS_ENV.proxyUrl]: declared(JOB_EGRESS_ENV.proxyUrl),
      [JOB_EGRESS_ENV.caBundle]: declared(JOB_EGRESS_ENV.caBundle),
    })
  } catch (error) {
    refuse((error as Error).message)
  }
})()

const verifierImageRef = declared(VERIFIER_IMAGE_ENV) || DEFAULT_VERIFIER_IMAGE
const verifierImage = await podmanValue(['image', 'inspect', verifierImageRef, '--format', '{{.Id}}'], `la imagen del verificador ${verifierImageRef} (no se descarga implícitamente)`)

const root = thyroxRoot()

/** La ruta de un hogar la decide el registro de P11 (`paths/declarations.py`), no una copia de su default. */
function registeredHome(key: string): string {
  const resolved = spawnSync('bash', [join(root, 'bin', 'ensure_homes'), '--resolve', key], { encoding: 'utf8' })
  const path = resolved.stdout.trim()
  if (resolved.status !== 0 || !path) refuse(`no se resolvió el hogar ${key}: ${resolved.stderr.trim() || `exit ${resolved.status}`}`)
  return path
}

const owner = `artifact-publish-${process.pid}`
const scratchDir = join(registeredHome(RUNTIME_HOME_KEY), 'artifact-verify', owner)
await mkdir(dirname(scratchDir), { recursive: true })

const baseRecord = JSON.parse(await readFile(values['record-file'] as string, 'utf8')) as Record<string, unknown>
const registryUrl = registryBaseUrl(credential.registry)
const location = { repository: values.repository as string, tag: values.tag as string }
const admission = createDiskAdmission({ thyroxRoot: root, path: dirname(scratchDir), ownerPid: process.pid })

const outcome = await publishAndVerify(
  {
    sourceDir,
    exclude: (values.exclude as string).split(',').map(name => name.trim()).filter(Boolean),
    mediaTypeOf,
    artifactType: values['artifact-type'] as string,
    recordFor: files => ({ ...baseRecord, files }),
    location,
  },
  {
    publisher: createOciArtifactRegistry({
      baseUrl: registryUrl,
      credential: { kind: 'basic', username: credential.username, secret: () => credential.revealToken() },
      trace: line => process.stderr.write(`publish-artifact: ${line}\n`),
    }),
    verifier: createPodmanJobVerifier({
      podman,
      image: verifierImage,
      bunPath: process.execPath,
      repositoryRoot: root,
      scratchDir,
      registryUrl,
      egress,
      owner: { kind: 'lab', id: owner, pid: process.pid },
      workerId: owner,
      limits: VERIFIER_LIMITS,
    }),
    admitDisk: needBytes => admission.admit(needBytes),
    releaseDisk: () => admission.release(),
  },
)

const record = publicationRecord(outcome, credential.registry, location.tag, new Date().toISOString())
await mkdir(dirname(values.out as string), { recursive: true })
await writeFile(values.out as string, `${JSON.stringify(record, null, 2)}\n`)
process.stderr.write(`publish-artifact: ${outcome.status}${outcome.status === 'verified' ? ` ${credential.registry}/${outcome.pinned.repository}@${outcome.pinned.digest}` : ''}\n`)
process.exit(publicationExitCode(outcome))

/**
 * Probar que la copia remota de un artefacto es legible y exacta
 * (TASK-THYROX-0728), separado de dónde corre la prueba.
 *
 * `verifyPublishedArtifact` es el método: resolver el tag por HEAD con un
 * consumidor sin credencial, exigir que apunte al digest publicado, y
 * materializar blob a blob verificando cada sha256 y borrando cada blob
 * antes de bajar el siguiente. El disco que consume se mide, no se supone.
 *
 * Quién lo ejecuta es un `ArtifactVerifier`: en proceso para las suites, o
 * como trabajo de la primitiva de Podman (`podmanJobVerifier.ts`) para que
 * la prueba no comparta el almacenamiento ni las credenciales del
 * publicador.
 */
import { rm } from 'node:fs/promises'

import type { ArtifactLocation, ArtifactRegistry, ArtifactResult, MaterializedFile, PinnedArtifact } from './artifactRegistry.js'

export interface Verification {
  readonly resolvedDigest: string
  readonly blobsVerified: readonly MaterializedFile[]
  /** Disco consumido como máximo durante la verificación, medido. */
  readonly measuredPeakBytes: number
}

/** El trabajo que verifica terminó sin dejar veredicto: ni el registry ni el artefacto respondieron mal. */
export interface VerificationJobFailure {
  readonly status: 'job_failed'
  readonly exitCode: number
  readonly detail: string
}

export type VerificationFailure = Exclude<ArtifactResult<unknown>, { status: 'success' }> | VerificationJobFailure

export type VerificationOutcome =
  | { readonly status: 'verified'; readonly verification: Verification }
  | { readonly status: 'unverified'; readonly result: VerificationFailure }

export interface ArtifactVerifier {
  verify(pinned: PinnedArtifact, location: ArtifactLocation): Promise<VerificationOutcome>
}

export interface VerificationContext {
  /** Consumidor anónimo: lo que prueba que el artefacto es legible sin credencial. */
  readonly consumer: ArtifactRegistry
  /** Directorio donde se materializa cada blob, uno a la vez; se borra al terminar. */
  readonly verifyDir: string
  /** Bytes libres del disco donde verifica; se muestrean para medir el pico real. */
  readonly freeBytes: () => number
}

export async function verifyPublishedArtifact(
  context: VerificationContext,
  pinned: PinnedArtifact,
  location: ArtifactLocation,
): Promise<VerificationOutcome> {
  try {
    const resolved = await context.consumer.resolveArtifact(location)
    if (resolved.status !== 'success') return { status: 'unverified', result: resolved }
    if (resolved.value.digest !== pinned.digest) {
      return { status: 'unverified', result: { status: 'integrity_error', detail: `el tag resuelve a ${resolved.value.digest}, no a ${pinned.digest}` } }
    }
    const startFree = context.freeBytes()
    let lowestFree = startFree
    const pulled = await context.consumer.pullArtifact(pinned, context.verifyDir, {
      discardAfterVerify: true,
      onVerified: () => { lowestFree = Math.min(lowestFree, context.freeBytes()) },
    })
    if (pulled.status !== 'success') return { status: 'unverified', result: pulled }
    return {
      status: 'verified',
      verification: { resolvedDigest: resolved.value.digest, blobsVerified: pulled.value, measuredPeakBytes: startFree - lowestFree },
    }
  } finally {
    await rm(context.verifyDir, { recursive: true, force: true })
  }
}

export function createInProcessVerifier(context: VerificationContext): ArtifactVerifier {
  return { verify: (pinned, location) => verifyPublishedArtifact(context, pinned, location) }
}
