/** PF_EXITING (`include/linux/sched.h`): el proceso ya entró en do_exit y su cgroup se desligó. */
const PF_EXITING = 0x4

function isExiting(flags: string | undefined): boolean {
  return (Number(flags) & PF_EXITING) !== 0
